import type { SpellEntry } from '../types'

// Magias do SRD 5.1 (5º nível), traduzidas para o português do Brasil. Alcances em metros.
export const SPELLS_NIVEL5: SpellEntry[] = [
  { key: "animate_objects", name: "Animar Objetos", original: "Animate Objects", level: 5, school: "transmutation", concentration: true, castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true}, duration: "Concentração, até 1 minuto", classes: ["bard", "sorcerer", "wizard"], text: ["Objetos ganham vida sob o seu comando. Escolha até dez objetos não mágicos ao alcance que não estejam sendo vestidos nem carregados. Alvos Médios contam como dois objetos, alvos Grandes contam como quatro objetos e alvos Imensos contam como oito objetos. Você não pode animar objetos maiores que Imensos. Cada alvo se anima e se torna uma criatura sob seu controle até a magia terminar ou até ser reduzido a 0 pontos de vida.", "Com uma ação bônus, você pode comandar mentalmente qualquer criatura que tenha criado com esta magia, se ela estiver a até 150 metros de você (se controlar várias criaturas, pode comandar qualquer uma ou todas ao mesmo tempo, dando o mesmo comando a cada uma). Você decide que ação a criatura realizará e para onde se moverá no turno seguinte, ou pode dar uma ordem geral, como guardar uma câmara ou corredor específico. Se não der comandos, a criatura apenas se defende de criaturas hostis. Depois de receber uma ordem, a criatura continua a segui-la até a tarefa ser concluída.", "Estatísticas dos objetos animados (tamanho: PV, CA, ataque, Força, Destreza):", "• Miúdo: 20 PV, CA 18, +8 para acertar e 1d4 + 4 de dano, For 4, Des 18", "• Pequeno: 25 PV, CA 16, +6 para acertar e 1d8 + 2 de dano, For 6, Des 14", "• Médio: 40 PV, CA 13, +5 para acertar e 2d6 + 1 de dano, For 10, Des 12", "• Grande: 50 PV, CA 10, +6 para acertar e 2d10 + 2 de dano, For 14, Des 10", "• Imenso: 80 PV, CA 10, +8 para acertar e 2d12 + 4 de dano, For 18, Des 6", "Um objeto animado é um constructo com CA, pontos de vida, ataques, Força e Destreza determinados pelo seu tamanho. Sua Constituição é 10, sua Inteligência e Sabedoria são 3 e seu Carisma é 1. Seu deslocamento é de 9 metros; se o objeto não tiver pernas ou outros apêndices que possa usar para locomoção, ele tem, em vez disso, deslocamento de voo de 9 metros e pode flutuar. Se o objeto estiver firmemente preso a uma superfície ou a um objeto maior, como uma corrente chumbada numa parede, seu deslocamento é 0. Ele tem visão às cegas com raio de 9 metros e é cego além dessa distância. Quando o objeto animado chega a 0 pontos de vida, ele volta à forma de objeto original, e qualquer dano restante passa para essa forma.", "Se você comandar um objeto a atacar, ele pode fazer um único ataque corpo a corpo contra uma criatura a até 1,5 metro dele. Ele faz um ataque de pancada com bônus de ataque e dano contundente determinados pelo seu tamanho. O Mestre pode decidir que um objeto específico causa dano cortante ou perfurante conforme sua forma."], higher: "Se você conjurar esta magia usando um espaço de magia de 6º nível ou superior, pode animar dois objetos adicionais para cada nível do espaço acima do 5º." },
  { key: "antilife_shell", name: "Concha Antivida", original: "Antilife Shell", level: 5, school: "abjuration", concentration: true, castingTime: "1 ação", range: "Pessoal (raio de 3 metros)", components: {"v": true, "s": true}, duration: "Concentração, até 1 hora", classes: ["druid"], text: ["Uma barreira cintilante se estende de você num raio de 3 metros e se move com você, permanecendo centrada em você e impedindo a passagem de criaturas que não sejam mortos-vivos e constructos. A barreira dura pela duração.", "A barreira impede que uma criatura afetada passe ou alcance através dela. Uma criatura afetada pode conjurar magias ou fazer ataques com armas à distância ou com alcance através da barreira.", "Se você se mover de modo que uma criatura afetada seja forçada a atravessar a barreira, a magia termina."] },
  { key: "arcane_hand", name: "Mão Arcana", original: "Arcane Hand", level: 5, school: "evocation", concentration: true, castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true, "m": "uma casca de ovo e uma luva de pele de cobra"}, duration: "Concentração, até 1 minuto", classes: ["wizard"], text: ["Você cria uma mão Grande de força cintilante e translúcida num espaço desocupado que possa ver ao alcance. A mão dura pela duração da magia e se move sob o seu comando, imitando os movimentos da sua própria mão.", "A mão é um objeto com CA 20 e pontos de vida iguais ao seu máximo de pontos de vida. Se chegar a 0 pontos de vida, a magia termina. Ela tem Força 26 (+8) e Destreza 10 (+0). A mão não preenche seu espaço.", "Ao conjurar a magia, e com uma ação bônus nos turnos seguintes, você pode mover a mão até 18 metros e então causar um dos efeitos a seguir com ela.", "Punho Cerrado. A mão golpeia uma criatura ou objeto a até 1,5 metro dela. Faça um ataque de magia corpo a corpo pela mão usando suas estatísticas de jogo. Se acertar, o alvo sofre 4d8 de dano de energia.", "Mão Poderosa. A mão tenta empurrar uma criatura a até 1,5 metro dela numa direção que você escolher. Faça um teste com a Força da mão contestado pelo teste de Força (Atletismo) do alvo. Se o alvo for Médio ou menor, você tem vantagem no teste. Se for bem-sucedido, a mão empurra o alvo 1,5 metro mais uma distância em metros igual a 1,5 vez seu modificador de atributo de conjuração. A mão se move com o alvo para permanecer a até 1,5 metro dele.", "Mão Agarradora. A mão tenta agarrar uma criatura Imensa ou menor a até 1,5 metro dela. Você usa o valor de Força da mão para resolver o agarrão. Se o alvo for Médio ou menor, você tem vantagem no teste. Enquanto a mão estiver agarrando o alvo, você pode usar uma ação bônus para fazer a mão esmagá-lo. Quando faz isso, o alvo sofre dano contundente igual a 2d6 + seu modificador de atributo de conjuração.", "Mão Interposta. A mão se interpõe entre você e uma criatura que você escolher até você dar à mão um comando diferente. A mão se move para permanecer entre você e o alvo, concedendo a você meia cobertura contra o alvo. O alvo não pode atravessar o espaço da mão se seu valor de Força for igual ou menor que o da mão. Se o valor de Força dele for maior que o da mão, o alvo pode se mover em sua direção através do espaço da mão, mas esse espaço é terreno difícil para ele."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o dano da opção punho cerrado aumenta em 2d8 e o dano da opção mão agarradora aumenta em 2d6 para cada nível do espaço acima do 5º." },
  { key: "awaken", name: "Despertar", original: "Awaken", level: 5, school: "transmutation", castingTime: "8 horas", range: "Toque", components: {"v": true, "s": true, "m": "uma ágata no valor de pelo menos 1.000 po, que a magia consome"}, duration: "Instantânea", classes: ["bard", "druid"], text: ["Depois de gastar o tempo de conjuração traçando caminhos mágicos dentro de uma gema preciosa, você toca um animal ou planta de tamanho Imenso ou menor. O alvo precisa ter nenhum valor de Inteligência ou Inteligência 3 ou menos. O alvo passa a ter Inteligência 10. O alvo também ganha a capacidade de falar um idioma que você conheça. Se o alvo for uma planta, ele ganha a capacidade de mover seus membros, raízes, trepadeiras e similares, e ganha sentidos semelhantes aos de um humano. Seu Mestre escolhe estatísticas apropriadas para a planta desperta, como as de um arbusto desperto ou de uma árvore desperta.", "O animal ou planta desperto fica enfeitiçado por você por 30 dias ou até você ou seus companheiros fazerem qualquer coisa prejudicial a ele. Quando a condição de enfeitiçado termina, a criatura desperta escolhe se permanecerá amistosa com você, com base em como você a tratou enquanto estava enfeitiçada."] },
  { key: "cloudkill", name: "Nuvem Mortal", original: "Cloudkill", level: 5, school: "conjuration", concentration: true, castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true}, duration: "Concentração, até 10 minutos", classes: ["sorcerer", "wizard"], text: ["Você cria uma esfera de névoa venenosa verde-amarelada com 6 metros de raio centrada num ponto à sua escolha ao alcance. A névoa contorna esquinas. Ela dura pela duração ou até um vento forte dispersá-la, encerrando a magia. Sua área fica fortemente obscurecida.", "Quando uma criatura entra na área da magia pela primeira vez num turno ou começa o turno ali, ela precisa fazer uma salvaguarda de Constituição. A criatura sofre 5d8 de dano de veneno se falhar, ou metade desse dano se for bem-sucedida. As criaturas são afetadas mesmo que prendam a respiração ou não precisem respirar.", "A névoa se move 3 metros para longe de você no início de cada um dos seus turnos, rolando ao longo da superfície do chão. Os vapores, sendo mais pesados que o ar, afundam até o nível mais baixo do terreno, até mesmo descendo por aberturas."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 5º." },
  { key: "commune", name: "Comunhão", original: "Commune", level: 5, school: "divination", ritual: true, castingTime: "1 minuto", range: "Pessoal", components: {"v": true, "s": true, "m": "incenso e um frasco de água benta ou profana"}, duration: "1 minuto", classes: ["cleric"], text: ["Você entra em contato com sua divindade ou um intermediário divino e faz até três perguntas que possam ser respondidas com sim ou não. Você precisa fazer suas perguntas antes de a magia terminar. Você recebe uma resposta correta para cada pergunta.", "Seres divinos não são necessariamente oniscientes, então você pode receber \"incerto\" como resposta se uma pergunta se referir a informações além do conhecimento da divindade. Num caso em que uma resposta de uma palavra possa ser enganosa ou contrária aos interesses da divindade, o Mestre pode oferecer uma frase curta como resposta.", "Se você conjurar a magia duas ou mais vezes antes de concluir o próximo descanso longo, há 25% de chance cumulativa, a cada conjuração após a primeira, de não receber resposta. O Mestre faz essa rolagem em segredo."] },
  { key: "commune_with_nature", name: "Comunhão com a Natureza", original: "Commune with Nature", level: 5, school: "divination", ritual: true, castingTime: "1 minuto", range: "Pessoal", components: {"v": true, "s": true}, duration: "Instantânea", classes: ["druid", "ranger"], text: ["Você se torna brevemente um com a natureza e obtém conhecimento do território ao redor. Ao ar livre, a magia dá conhecimento do terreno a até 4,5 km de você. Em cavernas e outros ambientes subterrâneos naturais, o raio é limitado a 90 metros. A magia não funciona onde a natureza foi substituída por construções, como em masmorras e cidades.", "Você obtém instantaneamente conhecimento de até três fatos à sua escolha sobre qualquer um dos seguintes assuntos relativos à área:", "• terreno e corpos d'água", "• plantas, minerais, animais ou povos predominantes", "• celestiais, fadas, ínferos, elementais ou mortos-vivos poderosos", "• influência de outros planos de existência", "• construções", "Por exemplo, você poderia determinar a localização de mortos-vivos poderosos na área, a localização das principais fontes de água potável segura e a localização de cidades próximas."] },
  { key: "cone_of_cold", name: "Cone de Frio", original: "Cone of Cold", level: 5, school: "evocation", castingTime: "1 ação", range: "Pessoal (cone de 18 metros)", components: {"v": true, "s": true, "m": "um pequeno cone de cristal ou vidro"}, duration: "Instantânea", classes: ["sorcerer", "wizard"], text: ["Uma rajada de ar gélido irrompe das suas mãos. Cada criatura num cone de 18 metros precisa fazer uma salvaguarda de Constituição. Uma criatura sofre 8d8 de dano de frio se falhar, ou metade desse dano se for bem-sucedida.", "Uma criatura morta por esta magia se torna uma estátua congelada até derreter."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 5º." },
  { key: "conjure_elemental", name: "Invocar Elemental", original: "Conjure Elemental", level: 5, school: "conjuration", concentration: true, castingTime: "1 minuto", range: "27 metros", components: {"v": true, "s": true, "m": "incenso queimando para o ar, argila macia para a terra, enxofre e fósforo para o fogo, ou água e areia para a água"}, duration: "Concentração, até 1 hora", classes: ["druid", "wizard"], text: ["Você convoca um servo elemental. Escolha uma área de ar, terra, fogo ou água que preencha um cubo de 3 metros ao alcance. Um elemental de nível de desafio 5 ou menor, apropriado à área escolhida, surge num espaço desocupado a até 3 metros dela. Por exemplo, um elemental do fogo emerge de uma fogueira, e um elemental da terra se ergue do chão. O elemental desaparece ao chegar a 0 pontos de vida ou quando a magia termina.", "O elemental é amistoso com você e seus companheiros pela duração. Role a iniciativa do elemental, que tem seus próprios turnos. Ele obedece a quaisquer comandos verbais que você der (sem exigir ação sua). Se você não der comandos ao elemental, ele se defende de criaturas hostis, mas, fora isso, não realiza ações.", "Se sua concentração for quebrada, o elemental não desaparece. Em vez disso, você perde o controle do elemental, ele se torna hostil a você e seus companheiros e pode atacar. Um elemental fora de controle não pode ser dispensado por você e desaparece 1 hora depois de ser convocado. O Mestre tem as estatísticas do elemental."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o nível de desafio aumenta em 1 para cada nível do espaço acima do 5º." },
  { key: "contact_other_plane", name: "Contatar Outro Plano", original: "Contact Other Plane", level: 5, school: "divination", ritual: true, castingTime: "1 minuto", range: "Pessoal", components: {"v": true, "s": false}, duration: "1 minuto", classes: ["warlock", "wizard"], text: ["Você entra em contato mental com um semideus, o espírito de um sábio morto há muito tempo ou outra entidade misteriosa de outro plano. Contatar essa inteligência extraplanar pode abalar ou até quebrar sua mente. Ao conjurar a magia, faça uma salvaguarda de Inteligência com CD 15. Se falhar, você sofre 6d6 de dano psíquico e fica insano até concluir um descanso longo. Enquanto insano, você não pode realizar ações, não entende o que outras criaturas dizem, não consegue ler e fala apenas bobagens. Uma magia restauração maior conjurada em você encerra esse efeito.", "Se for bem-sucedido na salvaguarda, você pode fazer até cinco perguntas à entidade. Você precisa fazer suas perguntas antes de a magia terminar. O Mestre responde cada pergunta com uma palavra, como \"sim\", \"não\", \"talvez\", \"nunca\", \"irrelevante\" ou \"incerto\" (se a entidade não souber a resposta). Se uma resposta de uma palavra for enganosa, o Mestre pode oferecer uma frase curta como resposta."] },
  { key: "contagion", name: "Contágio", original: "Contagion", level: 5, school: "necromancy", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true}, duration: "7 dias", classes: ["cleric", "druid"], text: ["Seu toque inflige doença. Faça um ataque de magia corpo a corpo contra uma criatura ao seu alcance. Se acertar, você aflige a criatura com uma doença à sua escolha entre as descritas abaixo.", "No fim de cada turno do alvo, ele precisa fazer uma salvaguarda de Constituição. Após falhar em três dessas salvaguardas, os efeitos da doença duram pela duração e a criatura deixa de fazer essas salvaguardas. Após ser bem-sucedida em três dessas salvaguardas, a criatura se recupera da doença, e a magia termina.", "Como esta magia induz uma doença natural no alvo, qualquer efeito que remova uma doença ou atenue seus efeitos se aplica a ela.", "Doença Cegante. A dor domina a mente da criatura, e seus olhos ficam brancos como leite. A criatura tem desvantagem em testes de Sabedoria e salvaguardas de Sabedoria e fica cega.", "Febre Imunda. Uma febre violenta toma o corpo da criatura. A criatura tem desvantagem em testes de Força, salvaguardas de Força e jogadas de ataque que usem Força.", "Carne Podre. A carne da criatura apodrece. A criatura tem desvantagem em testes de Carisma e vulnerabilidade a todo dano.", "Fogo Mental. A mente da criatura entra em febre. A criatura tem desvantagem em testes de Inteligência e salvaguardas de Inteligência, e se comporta, durante o combate, como se estivesse sob os efeitos da magia confusão.", "Convulsão. A criatura é tomada por tremores. A criatura tem desvantagem em testes de Destreza, salvaguardas de Destreza e jogadas de ataque que usem Destreza.", "Perdição Viscosa. A criatura começa a sangrar sem controle. A criatura tem desvantagem em testes de Constituição e salvaguardas de Constituição. Além disso, sempre que sofre dano, ela fica atordoada até o fim do seu próximo turno."] },
  { key: "creation", name: "Criação", original: "Creation", level: 5, school: "illusion", castingTime: "1 minuto", range: "9 metros", components: {"v": true, "s": true, "m": "um minúsculo pedaço de matéria do mesmo tipo do item que você pretende criar"}, duration: "Especial", classes: ["sorcerer", "wizard"], text: ["Você puxa fiapos de matéria sombria do Pendor das Sombras para criar um objeto não vivo de matéria vegetal ao alcance: tecidos, corda, madeira ou algo semelhante. Você também pode usar esta magia para criar objetos minerais, como pedra, cristal ou metal. O objeto criado não pode ser maior que um cubo de 1,5 metro, e precisa ter uma forma e um material que você já tenha visto.", "A duração depende do material do objeto. Se o objeto for composto de vários materiais, use a menor duração.", "• Matéria vegetal: 1 dia", "• Pedra ou cristal: 12 horas", "• Metais preciosos: 1 hora", "• Gemas: 10 minutos", "• Adamante ou mithral: 1 minuto", "Usar qualquer material criado por esta magia como componente material de outra magia faz essa magia falhar."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o cubo aumenta em 1,5 metro para cada nível do espaço acima do 5º." },
  { key: "dispel_evil_and_good", name: "Dissipar o Bem e o Mal", original: "Dispel Evil and Good", level: 5, school: "abjuration", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true, "m": "água benta ou prata e ferro em pó"}, duration: "Concentração, até 1 minuto", classes: ["cleric", "paladin"], text: ["Energia cintilante cerca e protege você de fadas, mortos-vivos e criaturas originárias de além do Plano Material. Pela duração, celestiais, elementais, fadas, ínferos e mortos-vivos têm desvantagem nas jogadas de ataque contra você.", "Você pode encerrar a magia antes usando uma das seguintes funções especiais.", "Quebrar Encantamento. Com sua ação, você toca uma criatura ao seu alcance que esteja enfeitiçada, amedrontada ou possuída por um celestial, elemental, fada, ínfero ou morto-vivo. A criatura que você tocar deixa de estar enfeitiçada, amedrontada ou possuída por essas criaturas.", "Dispensa. Com sua ação, faça um ataque de magia corpo a corpo contra um celestial, elemental, fada, ínfero ou morto-vivo ao seu alcance. Se acertar, você tenta mandar a criatura de volta ao seu plano natal. A criatura precisa ser bem-sucedida em uma salvaguarda de Carisma ou será enviada de volta ao seu plano natal (se já não estiver lá). Se não estiverem no plano natal, mortos-vivos são enviados ao Pendor das Sombras, e fadas são enviadas ao Reino Selvagem."] },
  { key: "dominate_person", name: "Dominar Pessoa", original: "Dominate Person", level: 5, school: "enchantment", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true}, duration: "Concentração, até 1 minuto", classes: ["bard", "sorcerer", "wizard"], text: ["Você tenta enfeitiçar um humanoide que possa ver ao alcance. Ele precisa ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará enfeitiçado por você pela duração. Se você ou criaturas amistosas com você estiverem lutando contra ele, ele tem vantagem na salvaguarda.", "Enquanto o alvo estiver enfeitiçado, você tem um vínculo telepático com ele, contanto que ambos estejam no mesmo plano de existência. Você pode usar esse vínculo telepático para dar comandos à criatura enquanto estiver consciente (sem exigir ação), e ela faz o possível para obedecer. Você pode especificar um curso de ação simples e geral, como \"Ataque aquela criatura\", \"Corra até lá\" ou \"Traga aquele objeto\". Se a criatura cumprir a ordem e não receber mais instruções suas, ela se defende e se preserva da melhor forma possível.", "Você pode usar sua ação para assumir controle total e preciso do alvo. Até o fim do seu próximo turno, a criatura realiza apenas as ações que você escolher e não faz nada que você não permita. Durante esse tempo, você também pode fazer a criatura usar uma reação, mas isso exige que você use a sua própria reação também.", "Cada vez que o alvo sofre dano, ele faz uma nova salvaguarda de Sabedoria contra a magia. Se for bem-sucedido, a magia termina."], higher: "Quando você conjura esta magia com um espaço de magia de 6º nível, a duração é concentração, até 10 minutos. Com um espaço de 7º nível, a duração é concentração, até 1 hora. Com um espaço de 8º nível ou superior, a duração é concentração, até 8 horas." },
  { key: "dream", name: "Sonho", original: "Dream", level: 5, school: "illusion", castingTime: "1 minuto", range: "Especial", components: {"v": true, "s": true, "m": "um punhado de areia, uma gota de tinta e uma pena de escrever arrancada de uma ave adormecida"}, duration: "8 horas", classes: ["bard", "warlock", "wizard"], text: ["Esta magia molda os sonhos de uma criatura. Escolha uma criatura conhecida por você como alvo da magia. O alvo precisa estar no mesmo plano de existência que você. Criaturas que não dormem, como os elfos, não podem ser contatadas por esta magia. Você, ou uma criatura voluntária que tocar, entra em estado de transe, agindo como mensageiro. Enquanto estiver em transe, o mensageiro tem consciência do que o cerca, mas não pode realizar ações nem se mover.", "Se o alvo estiver dormindo, o mensageiro aparece nos sonhos do alvo e pode conversar com ele enquanto ele continuar dormindo, durante a duração da magia. O mensageiro também pode moldar o ambiente do sonho, criando paisagens, objetos e outras imagens. O mensageiro pode sair do transe a qualquer momento, encerrando o efeito da magia antes do tempo. O alvo se lembra perfeitamente do sonho ao acordar. Se o alvo estiver acordado quando você conjurar a magia, o mensageiro sabe disso e pode encerrar o transe (e a magia) ou esperar o alvo adormecer, quando o mensageiro aparece nos sonhos dele.", "Você pode fazer o mensageiro parecer monstruoso e aterrorizante para o alvo. Se fizer isso, o mensageiro pode entregar uma mensagem de no máximo dez palavras, e então o alvo precisa fazer uma salvaguarda de Sabedoria. Se falhar, ecos da monstruosidade fantasmagórica geram um pesadelo que dura todo o sono do alvo e o impede de receber qualquer benefício desse descanso. Além disso, quando o alvo acorda, ele sofre 3d6 de dano psíquico.", "Se você tiver uma parte do corpo, um cacho de cabelo, uma apara de unha ou porção semelhante do corpo do alvo, o alvo faz a salvaguarda com desvantagem."] },
  { key: "flame_strike", name: "Coluna de Chamas", original: "Flame Strike", level: 5, school: "evocation", castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true, "m": "uma pitada de enxofre"}, duration: "Instantânea", classes: ["cleric"], text: ["Uma coluna vertical de fogo divino desce rugindo dos céus num local que você especificar. Cada criatura num cilindro de 3 metros de raio e 12 metros de altura centrado num ponto ao alcance precisa fazer uma salvaguarda de Destreza. Uma criatura sofre 4d6 de dano de fogo e 4d6 de dano radiante se falhar, ou metade desse dano se for bem-sucedida."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o dano de fogo ou o dano radiante (à sua escolha) aumenta em 1d6 para cada nível do espaço acima do 5º." },
  { key: "geas", name: "Missão", original: "Geas", level: 5, school: "enchantment", castingTime: "1 minuto", range: "18 metros", components: {"v": true, "s": false}, duration: "30 dias", classes: ["bard", "cleric", "druid", "paladin", "wizard"], text: ["Você coloca um comando mágico numa criatura que possa ver ao alcance, forçando-a a cumprir algum serviço ou abster-se de alguma ação ou linha de conduta como você decidir. Se a criatura puder entender você, ela precisa ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará enfeitiçada por você pela duração. Enquanto a criatura estiver enfeitiçada por você, ela sofre 5d10 de dano psíquico cada vez que agir de maneira diretamente contrária às suas instruções, mas não mais de uma vez por dia. Uma criatura que não possa entender você não é afetada pela magia.", "Você pode dar qualquer comando que escolher, exceto uma atividade que resultaria em morte certa. Se der um comando suicida, a magia termina.", "Você pode encerrar a magia antes usando uma ação para dissipá-la. Uma magia remover maldição, restauração maior ou desejo também a encerra."], higher: "Quando você conjura esta magia usando um espaço de magia de 7º ou 8º nível, a duração é de 1 ano. Quando conjura esta magia usando um espaço de magia de 9º nível, a magia dura até ser encerrada por uma das magias mencionadas acima." },
  { key: "greater_restoration", name: "Restauração Maior", original: "Greater Restoration", level: 5, school: "abjuration", castingTime: "1 ação", range: "Toque", components: {"v": true, "s": true, "m": "pó de diamante no valor de pelo menos 100 po, que a magia consome"}, duration: "Instantânea", classes: ["bard", "cleric", "druid"], text: ["Você imbui uma criatura que toca com energia positiva para desfazer um efeito debilitante. Você pode reduzir o nível de exaustão do alvo em um, ou encerrar um dos seguintes efeitos sobre o alvo:", "• Um efeito que enfeitiçou ou petrificou o alvo", "• Uma maldição, incluindo a sintonização do alvo com um item mágico amaldiçoado", "• Qualquer redução em um dos valores de atributo do alvo", "• Um efeito que reduza o máximo de pontos de vida do alvo"] },
  { key: "hallow", name: "Santificar", original: "Hallow", level: 5, school: "evocation", castingTime: "24 horas", range: "Toque", components: {"v": true, "s": true, "m": "ervas, óleos e incenso no valor de pelo menos 1.000 po, que a magia consome"}, duration: "Até ser dissipada", classes: ["cleric"], text: ["Você toca um ponto e imbui uma área ao redor dele com poder sagrado (ou profano). A área pode ter um raio de até 18 metros, e a magia falha se o raio incluir uma área já sob o efeito de uma magia santificar. A área afetada está sujeita aos efeitos a seguir.", "Primeiro, celestiais, elementais, fadas, ínferos e mortos-vivos não podem entrar na área, nem essas criaturas podem enfeitiçar, amedrontar ou possuir criaturas dentro dela. Qualquer criatura enfeitiçada, amedrontada ou possuída por uma dessas criaturas deixa de estar enfeitiçada, amedrontada ou possuída ao entrar na área. Você pode excluir um ou mais desses tipos de criatura deste efeito.", "Segundo, você pode vincular um efeito extra à área. Escolha o efeito da lista a seguir ou um efeito oferecido pelo Mestre. Alguns desses efeitos se aplicam a criaturas na área; você pode designar se o efeito se aplica a todas as criaturas, criaturas que seguem uma divindade ou líder específico, ou criaturas de um tipo específico, como orcs ou trolls. Quando uma criatura que seria afetada entra na área da magia pela primeira vez num turno ou começa o turno ali, ela pode fazer uma salvaguarda de Carisma. Se for bem-sucedida, a criatura ignora o efeito extra até sair da área.", "Coragem. Criaturas afetadas não podem ser amedrontadas enquanto estiverem na área.", "Escuridão. Escuridão preenche a área. Luz normal, assim como luz mágica criada por magias de nível inferior ao do espaço usado para conjurar esta magia, não consegue iluminar a área.", "Luz do Dia. Luz plena preenche a área. Escuridão mágica criada por magias de nível inferior ao do espaço usado para conjurar esta magia não consegue apagar a luz.", "Proteção contra Energia. Criaturas afetadas na área têm resistência a um tipo de dano à sua escolha, exceto contundente, perfurante ou cortante.", "Vulnerabilidade a Energia. Criaturas afetadas na área têm vulnerabilidade a um tipo de dano à sua escolha, exceto contundente, perfurante ou cortante.", "Descanso Eterno. Corpos mortos sepultados na área não podem ser transformados em mortos-vivos.", "Interferência Extradimensional. Criaturas afetadas não podem se mover ou viajar usando teletransporte ou meios extradimensionais ou interplanares.", "Medo. Criaturas afetadas ficam amedrontadas enquanto estiverem na área.", "Silêncio. Nenhum som pode emanar de dentro da área, e nenhum som pode alcançá-la.", "Idiomas. Criaturas afetadas podem se comunicar com qualquer outra criatura na área, mesmo que não compartilhem um idioma."] },
  { key: "hold_monster", name: "Imobilizar Monstro", original: "Hold Monster", level: 5, school: "enchantment", concentration: true, castingTime: "1 ação", range: "27 metros", components: {"v": true, "s": true, "m": "um pequeno pedaço reto de ferro"}, duration: "Concentração, até 1 minuto", classes: ["bard", "sorcerer", "warlock", "wizard"], text: ["Escolha uma criatura que possa ver ao alcance. O alvo precisa ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará paralisado pela duração. Esta magia não tem efeito sobre mortos-vivos. No fim de cada um dos seus turnos, o alvo pode fazer outra salvaguarda de Sabedoria. Se for bem-sucedido, a magia termina para ele."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 5º. As criaturas precisam estar a até 9 metros umas das outras quando você as escolhe." },
  { key: "insect_plague", name: "Praga de Insetos", original: "Insect Plague", level: 5, school: "conjuration", concentration: true, castingTime: "1 ação", range: "90 metros", components: {"v": true, "s": true, "m": "alguns grãos de açúcar, alguns grãos de cereal e uma mancha de gordura"}, duration: "Concentração, até 10 minutos", classes: ["cleric", "druid", "sorcerer"], text: ["Gafanhotos mordedores e fervilhantes preenchem uma esfera de 6 metros de raio centrada num ponto à sua escolha ao alcance. A esfera contorna esquinas. A esfera permanece pela duração, e sua área fica levemente obscurecida. A área da esfera é terreno difícil.", "Quando a área surge, cada criatura nela precisa fazer uma salvaguarda de Constituição. Uma criatura sofre 4d10 de dano perfurante se falhar, ou metade desse dano se for bem-sucedida. Uma criatura também precisa fazer essa salvaguarda quando entra na área da magia pela primeira vez num turno ou termina o turno ali."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 5º." },
  { key: "legend_lore", name: "Lenda", original: "Legend Lore", level: 5, school: "divination", castingTime: "10 minutos", range: "Pessoal", components: {"v": true, "s": true, "m": "incenso no valor de pelo menos 250 po, que a magia consome, e quatro tiras de marfim no valor de pelo menos 50 po cada"}, duration: "Instantânea", classes: ["bard", "cleric", "wizard"], text: ["Diga o nome ou descreva uma pessoa, lugar ou objeto. A magia traz à sua mente um breve resumo das tradições significativas sobre aquilo que você nomeou. A tradição pode consistir em histórias atuais, relatos esquecidos ou até saberes secretos que nunca foram amplamente conhecidos. Se aquilo que você nomeou não tiver importância lendária, você não obtém informação alguma. Quanto mais informações você já tiver sobre a coisa, mais precisas e detalhadas serão as informações que receber.", "As informações obtidas são exatas, mas podem vir em linguagem figurada. Por exemplo, se você tiver à mão um misterioso machado mágico, a magia pode render esta informação: \"Ai do malfeitor cuja mão tocar o machado, pois até o cabo corta a mão dos maus. Apenas um verdadeiro Filho da Pedra, amante e amado de Moradin, pode despertar os verdadeiros poderes do machado, e somente com a palavra sagrada Rudnogg nos lábios.\""] },
  { key: "mass_cure_wounds", name: "Curar Ferimentos em Massa", original: "Mass Cure Wounds", level: 5, school: "evocation", castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true}, duration: "Instantânea", classes: ["bard", "cleric", "druid"], text: ["Uma onda de energia curativa jorra de um ponto à sua escolha ao alcance. Escolha até seis criaturas numa esfera de 9 metros de raio centrada nesse ponto. Cada alvo recupera pontos de vida iguais a 3d8 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos nem constructos."], higher: "Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, a cura aumenta em 1d8 para cada nível do espaço acima do 5º." },
  { key: "mislead", name: "Despistar", original: "Mislead", level: 5, school: "illusion", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": false, "s": true}, duration: "Concentração, até 1 hora", classes: ["bard", "wizard"], text: ["Você fica invisível ao mesmo tempo que um duplo ilusório seu surge onde você está. O duplo dura pela duração, mas a invisibilidade termina se você atacar ou conjurar uma magia.", "Você pode usar sua ação para mover seu duplo ilusório até o dobro do seu deslocamento e fazê-lo gesticular, falar e se comportar da maneira que escolher.", "Você pode ver através dos olhos dele e ouvir através dos ouvidos dele como se estivesse onde ele está. Em cada um dos seus turnos, com uma ação bônus, você pode alternar entre usar os sentidos dele e usar os seus próprios, ou voltar. Enquanto usa os sentidos dele, você fica cego e surdo em relação ao seu próprio entorno."] },
  { key: "modify_memory", name: "Modificar Memória", original: "Modify Memory", level: 5, school: "enchantment", concentration: true, castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": true}, duration: "Concentração, até 1 minuto", classes: ["bard", "wizard"], text: ["Você tenta remodelar as memórias de outra criatura. Uma criatura que você possa ver precisa fazer uma salvaguarda de Sabedoria. Se você estiver lutando contra a criatura, ela tem vantagem na salvaguarda. Se falhar, o alvo fica enfeitiçado por você pela duração. O alvo enfeitiçado fica incapacitado e alheio ao que o cerca, embora ainda possa ouvir você. Se sofrer qualquer dano ou for alvo de outra magia, esta magia termina, e nenhuma das memórias do alvo é modificada.", "Enquanto esse encantamento durar, você pode afetar a memória do alvo sobre um evento que ele vivenciou nas últimas 24 horas e que durou no máximo 10 minutos. Você pode eliminar permanentemente toda a memória do evento, permitir que o alvo se lembre do evento com perfeita clareza e detalhes exatos, mudar sua memória dos detalhes do evento ou criar uma memória de algum outro evento.", "Você precisa falar com o alvo para descrever como as memórias dele são afetadas, e ele precisa ser capaz de entender seu idioma para as memórias modificadas se fixarem. A mente dele preenche quaisquer lacunas nos detalhes da sua descrição. Se a magia terminar antes de você ter terminado de descrever as memórias modificadas, a memória da criatura não é alterada. Caso contrário, as memórias modificadas se fixam quando a magia termina.", "Uma memória modificada não afeta necessariamente o comportamento de uma criatura, em especial se a memória contradiz as inclinações naturais, o alinhamento ou as crenças dela. Uma memória modificada ilógica, como implantar a lembrança de como a criatura gostou de se banhar em ácido, é descartada, talvez como um pesadelo. O Mestre pode considerar uma memória modificada absurda demais para afetar uma criatura de maneira significativa.", "Uma magia remover maldição ou restauração maior conjurada no alvo restaura a verdadeira memória da criatura."], higher: "Se você conjurar esta magia usando um espaço de magia de 6º nível ou superior, pode alterar as memórias do alvo sobre um evento que ocorreu até 7 dias atrás (6º nível), 30 dias atrás (7º nível), 1 ano atrás (8º nível) ou em qualquer momento do passado da criatura (9º nível)." },
  { key: "passwall", name: "Passa-Parede", original: "Passwall", level: 5, school: "transmutation", castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": true, "m": "uma pitada de sementes de gergelim"}, duration: "1 hora", classes: ["wizard"], text: ["Uma passagem surge num ponto à sua escolha que você possa ver, numa superfície de madeira, gesso ou pedra (como uma parede, teto ou piso) ao alcance, e dura pela duração. Você escolhe as dimensões da abertura: até 1,5 metro de largura, 2,4 metros de altura e 6 metros de profundidade. A passagem não cria instabilidade na estrutura ao redor.", "Quando a abertura desaparece, quaisquer criaturas ou objetos que ainda estejam na passagem criada pela magia são ejetados com segurança para o espaço desocupado mais próximo da superfície em que você conjurou a magia."] },
  { key: "planar_binding", name: "Aprisionamento Planar", original: "Planar Binding", level: 5, school: "abjuration", castingTime: "1 hora", range: "18 metros", components: {"v": true, "s": true, "m": "uma joia no valor de pelo menos 1.000 po, que a magia consome"}, duration: "24 horas", classes: ["bard", "cleric", "druid", "wizard"], text: ["Com esta magia, você tenta prender um celestial, elemental, fada ou ínfero a seu serviço. A criatura precisa estar ao alcance durante toda a conjuração da magia. (Normalmente, a criatura é primeiro convocada para o centro de um círculo mágico invertido, para mantê-la presa enquanto esta magia é conjurada.) Ao término da conjuração, o alvo precisa fazer uma salvaguarda de Carisma. Se falhar, ele fica preso a servi-lo pela duração. Se a criatura foi convocada ou criada por outra magia, a duração dessa magia é estendida para igualar a duração desta.", "Uma criatura presa precisa seguir suas instruções da melhor forma possível. Você pode comandar a criatura a acompanhá-lo numa aventura, guardar um local ou entregar uma mensagem. A criatura obedece à letra das suas instruções, mas, se for hostil a você, se esforça para distorcer suas palavras e alcançar os próprios objetivos. Se a criatura cumprir suas instruções por completo antes de a magia terminar, ela viaja até você para relatar o fato, se você estiver no mesmo plano de existência. Se você estiver num plano diferente, ela volta ao lugar onde você a prendeu e permanece lá até a magia terminar."], higher: "Quando você conjura esta magia usando um espaço de magia de nível superior, a duração aumenta para 10 dias com um espaço de 6º nível, 30 dias com um de 7º nível, 180 dias com um de 8º nível e um ano e um dia com um espaço de 9º nível." },
  { key: "raise_dead", name: "Reviver os Mortos", original: "Raise Dead", level: 5, school: "necromancy", castingTime: "1 hora", range: "Toque", components: {"v": true, "s": true, "m": "um diamante no valor de pelo menos 500 po, que a magia consome"}, duration: "Instantânea", classes: ["bard", "cleric", "paladin"], text: ["Você devolve à vida uma criatura morta que tocar, contanto que ela esteja morta há no máximo 10 dias. Se a alma da criatura estiver disposta e livre para voltar ao corpo, a criatura volta à vida com 1 ponto de vida.", "Esta magia também neutraliza quaisquer venenos e cura doenças não mágicas que afetavam a criatura no momento da morte. Porém, a magia não remove doenças mágicas, maldições ou efeitos semelhantes; se eles não forem removidos antes da conjuração da magia, fazem efeito quando a criatura volta à vida. A magia não pode trazer de volta à vida uma criatura morta-viva.", "Esta magia fecha todos os ferimentos mortais, mas não restaura partes do corpo ausentes. Se a criatura estiver sem partes do corpo ou órgãos essenciais à sua sobrevivência, como a cabeça, a magia falha automaticamente.", "Voltar dos mortos é uma provação. O alvo sofre -4 de penalidade em todas as jogadas de ataque, salvaguardas e testes de habilidade. Toda vez que o alvo conclui um descanso longo, a penalidade diminui em 1, até desaparecer."] },
  { key: "reincarnate", name: "Reencarnar", original: "Reincarnate", level: 5, school: "transmutation", castingTime: "1 hora", range: "Toque", components: {"v": true, "s": true, "m": "óleos e unguentos raros no valor de pelo menos 1.000 po, que a magia consome"}, duration: "Instantânea", classes: ["druid"], text: ["Você toca um humanoide morto ou um pedaço de um humanoide morto. Contanto que a criatura esteja morta há no máximo 10 dias, a magia forma um novo corpo adulto para ela e então chama a alma para entrar nesse corpo. Se a alma do alvo não estiver livre ou disposta a isso, a magia falha.", "A magia modela um novo corpo para a criatura habitar, o que provavelmente faz a raça da criatura mudar. O Mestre rola um d100 e consulta a tabela a seguir para determinar a forma que a criatura assume ao ser trazida de volta à vida, ou o Mestre escolhe uma forma.", "• 01 a 04: Draconato", "• 05 a 13: Anão da colina", "• 14 a 21: Anão da montanha", "• 22 a 25: Elfo negro", "• 26 a 34: Alto elfo", "• 35 a 42: Elfo da floresta", "• 43 a 46: Gnomo da floresta", "• 47 a 52: Gnomo das rochas", "• 53 a 56: Meio-elfo", "• 57 a 60: Meio-orc", "• 61 a 68: Halfling pés leves", "• 69 a 76: Halfling robusto", "• 77 a 96: Humano", "• 97 a 00: Tiefling", "A criatura reencarnada se lembra de sua vida e experiências anteriores. Ela mantém as capacidades que tinha na forma original, exceto que troca a raça original pela nova e muda suas características raciais de acordo."] },
  { key: "scrying", name: "Vidência", original: "Scrying", level: 5, school: "divination", concentration: true, castingTime: "10 minutos", range: "Pessoal", components: {"v": true, "s": true, "m": "um foco no valor de pelo menos 1.000 po, como uma bola de cristal, um espelho de prata ou uma fonte cheia de água benta"}, duration: "Concentração, até 10 minutos", classes: ["bard", "cleric", "druid", "warlock", "wizard"], text: ["Você pode ver e ouvir uma criatura específica à sua escolha que esteja no mesmo plano de existência que você. O alvo precisa fazer uma salvaguarda de Sabedoria, modificada pelo quanto você conhece o alvo e pelo tipo de ligação física que tem com ele. Se o alvo souber que você está conjurando esta magia, ele pode falhar na salvaguarda voluntariamente, se quiser ser observado.", "Conhecimento (modificador na salvaguarda):", "• De segunda mão (você ouviu falar do alvo): +5", "• Em primeira mão (você conheceu o alvo): +0", "• Familiar (você conhece bem o alvo): -5", "Ligação (modificador na salvaguarda):", "• Semelhança ou retrato: -2", "• Posse ou peça de roupa: -4", "• Parte do corpo, cacho de cabelo, apara de unha ou similar: -10", "Se for bem-sucedido, o alvo não é afetado, e você não pode usar esta magia contra ele de novo por 24 horas.", "Se falhar, a magia cria um sensor invisível a até 3 metros do alvo. Você pode ver e ouvir através do sensor como se estivesse lá. O sensor se move com o alvo, permanecendo a até 3 metros dele pela duração. Uma criatura que consiga ver objetos invisíveis vê o sensor como um orbe luminoso do tamanho do seu punho.", "Em vez de escolher uma criatura, você pode escolher como alvo desta magia um local que já tenha visto. Quando faz isso, o sensor surge nesse local e não se move."] },
  { key: "seeming", name: "Aparência Enganosa", original: "Seeming", level: 5, school: "illusion", castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": true}, duration: "8 horas", classes: ["bard", "sorcerer", "wizard"], text: ["Esta magia permite alterar a aparência de qualquer número de criaturas que você possa ver ao alcance. Você dá a cada alvo escolhido uma nova aparência ilusória. Um alvo involuntário pode fazer uma salvaguarda de Carisma, e, se for bem-sucedido, não é afetado por esta magia.", "A magia disfarça a aparência física, bem como roupas, armaduras, armas e equipamento. Você pode fazer cada criatura parecer 30 cm mais baixa ou mais alta e parecer magra, gorda ou intermediária. Você não pode mudar o tipo de corpo do alvo, então precisa escolher uma forma com a mesma disposição básica de membros. Fora isso, a extensão da ilusão fica a seu critério. A magia dura pela duração, a menos que você use sua ação para dissipá-la antes.", "As mudanças causadas por esta magia não resistem a uma inspeção física. Por exemplo, se você usar a magia para acrescentar um chapéu ao traje de uma criatura, objetos atravessam o chapéu, e quem o tocar não sentirá nada ou sentirá a cabeça e o cabelo da criatura. Se você usar a magia para parecer mais magro do que é, a mão de quem tentar tocá-lo esbarrará em você enquanto aparentemente ainda está no ar.", "Uma criatura pode usar sua ação para inspecionar um alvo e fazer um teste de Inteligência (Investigação) contra a CD de salvaguarda da sua magia. Se for bem-sucedida, ela percebe que o alvo está disfarçado."] },
  { key: "telekinesis", name: "Telecinésia", original: "Telekinesis", level: 5, school: "transmutation", concentration: true, castingTime: "1 ação", range: "18 metros", components: {"v": true, "s": true}, duration: "Concentração, até 10 minutos", classes: ["sorcerer", "wizard"], text: ["Você ganha a capacidade de mover ou manipular criaturas ou objetos com o pensamento. Ao conjurar a magia, e com sua ação a cada rodada pela duração, você pode exercer sua vontade sobre uma criatura ou objeto que possa ver ao alcance, causando o efeito apropriado abaixo. Você pode afetar o mesmo alvo rodada após rodada, ou escolher um novo a qualquer momento. Se trocar de alvo, o alvo anterior deixa de ser afetado pela magia.", "Criatura. Você pode tentar mover uma criatura Imensa ou menor. Faça um teste de habilidade com seu atributo de conjuração contestado pelo teste de Força da criatura. Se vencer a disputa, você move a criatura até 9 metros em qualquer direção, inclusive para cima, mas não além do alcance desta magia. Até o fim do seu próximo turno, a criatura fica impedida em sua pegada telecinética. Uma criatura erguida fica suspensa no ar.", "Nas rodadas seguintes, você pode usar sua ação para tentar manter a pegada telecinética sobre a criatura repetindo a disputa.", "Objeto. Você pode tentar mover um objeto que pese até 500 kg. Se o objeto não estiver sendo vestido ou carregado, você o move automaticamente até 9 metros em qualquer direção, mas não além do alcance desta magia.", "Se o objeto estiver sendo vestido ou carregado por uma criatura, você precisa fazer um teste de habilidade com seu atributo de conjuração contestado pelo teste de Força dessa criatura. Se for bem-sucedido, você tira o objeto dessa criatura e pode movê-lo até 9 metros em qualquer direção, mas não além do alcance desta magia.", "Você pode exercer controle fino sobre objetos com sua pegada telecinética, como manipular uma ferramenta simples, abrir uma porta ou recipiente, guardar ou retirar um item de um recipiente aberto ou despejar o conteúdo de um frasco."] },
  { key: "telepathic_bond", name: "Vínculo Telepático", original: "Telepathic Bond", level: 5, school: "divination", ritual: true, castingTime: "1 ação", range: "9 metros", components: {"v": true, "s": true, "m": "pedaços de casca de ovo de dois tipos diferentes de criaturas"}, duration: "1 hora", classes: ["wizard"], text: ["Você forja um elo telepático entre até oito criaturas voluntárias à sua escolha ao alcance, ligando psiquicamente cada criatura a todas as outras pela duração. Criaturas com valor de Inteligência 2 ou menos não são afetadas por esta magia.", "Até a magia terminar, os alvos podem se comunicar telepaticamente através do vínculo, compartilhem ou não um idioma. A comunicação é possível por qualquer distância, embora não possa se estender a outros planos de existência."] },
  { key: "teleportation_circle", name: "Círculo de Teletransporte", original: "Teleportation Circle", level: 5, school: "conjuration", castingTime: "1 minuto", range: "3 metros", components: {"v": true, "s": false, "m": "gizes e tintas raros infundidos com gemas preciosas no valor de 50 po, que a magia consome"}, duration: "1 rodada", classes: ["bard", "sorcerer", "wizard"], text: ["Ao conjurar a magia, você desenha no chão um círculo de 3 metros de diâmetro, inscrito com símbolos que ligam o seu local a um círculo de teletransporte permanente à sua escolha, cuja sequência de símbolos você conheça e que esteja no mesmo plano de existência que você. Um portal cintilante se abre dentro do círculo que você desenhou e permanece aberto até o fim do seu próximo turno. Qualquer criatura que entre no portal aparece instantaneamente a até 1,5 metro do círculo de destino, ou no espaço desocupado mais próximo, se aquele estiver ocupado.", "Muitos templos importantes, guildas e outros lugares relevantes têm círculos de teletransporte permanentes inscritos em algum lugar dentro de seus limites. Cada círculo desses inclui uma sequência única de símbolos, uma série de runas mágicas dispostas em um padrão particular. Quando você ganha a capacidade de conjurar esta magia, aprende as sequências de símbolos de dois destinos no Plano Material, determinados pelo Mestre. Você pode aprender sequências adicionais durante suas aventuras. Você pode memorizar uma nova sequência depois de estudá-la por 1 minuto.", "Você pode criar um círculo de teletransporte permanente conjurando esta magia no mesmo local todos os dias por um ano. Você não precisa usar o círculo para se teletransportar quando conjura a magia dessa forma."] },
  { key: "tree_stride", name: "Caminhar por Árvores", original: "Tree Stride", level: 5, school: "conjuration", concentration: true, castingTime: "1 ação", range: "Pessoal", components: {"v": true, "s": true}, duration: "Concentração, até 1 minuto", classes: ["druid", "ranger"], text: ["Você ganha a capacidade de entrar numa árvore e se mover de dentro dela para dentro de outra árvore do mesmo tipo a até 150 metros. Ambas as árvores precisam estar vivas e ser pelo menos do seu tamanho. Você precisa gastar 1,5 metro de movimento para entrar numa árvore. Você sabe instantaneamente a localização de todas as outras árvores do mesmo tipo a até 150 metros e, como parte do movimento usado para entrar na árvore, pode passar para uma dessas árvores ou sair da árvore em que está. Você surge num ponto à sua escolha a até 1,5 metro da árvore de destino, gastando mais 1,5 metro de movimento. Se não tiver mais movimento, você surge a até 1,5 metro da árvore em que entrou.", "Você pode usar essa capacidade de transporte uma vez por rodada pela duração. Você precisa terminar cada turno fora de uma árvore."] },
  { key: "wall_of_force", name: "Muralha de Energia", original: "Wall of Force", level: 5, school: "evocation", concentration: true, castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true, "m": "uma pitada de pó feito de uma gema transparente esmagada"}, duration: "Concentração, até 10 minutos", classes: ["wizard"], text: ["Uma muralha invisível de energia surge num ponto à sua escolha ao alcance. A muralha surge na orientação que você escolher, como barreira horizontal, vertical ou inclinada. Ela pode flutuar livremente ou se apoiar numa superfície sólida. Você pode moldá-la numa cúpula hemisférica ou numa esfera com raio de até 3 metros, ou pode formar uma superfície plana composta de dez painéis de 3 por 3 metros. Cada painel precisa ser contíguo a outro painel. Em qualquer forma, a muralha tem 6 mm de espessura. Ela dura pela duração. Se a muralha cortar o espaço de uma criatura quando surgir, a criatura é empurrada para um dos lados da muralha (à sua escolha).", "Nada pode atravessar fisicamente a muralha. Ela é imune a todo dano e não pode ser dissipada por dissipar magia. Uma magia desintegrar, porém, destrói a muralha instantaneamente. A muralha também se estende ao Plano Etéreo, bloqueando a viagem etérea através dela."] },
  { key: "wall_of_stone", name: "Muralha de Pedra", original: "Wall of Stone", level: 5, school: "evocation", concentration: true, castingTime: "1 ação", range: "36 metros", components: {"v": true, "s": true, "m": "um pequeno bloco de granito"}, duration: "Concentração, até 10 minutos", classes: ["druid", "sorcerer", "wizard"], text: ["Uma muralha não mágica de pedra sólida surge num ponto à sua escolha ao alcance. A muralha tem 15 cm de espessura e é composta de dez painéis de 3 por 3 metros. Cada painel precisa ser contíguo a pelo menos outro painel. Alternativamente, você pode criar painéis de 3 por 6 metros com apenas 7,5 cm de espessura.", "Se a muralha cortar o espaço de uma criatura quando surgir, a criatura é empurrada para um dos lados da muralha (à sua escolha). Se uma criatura ficasse cercada por todos os lados pela muralha (ou pela muralha e outra superfície sólida), essa criatura pode fazer uma salvaguarda de Destreza. Se for bem-sucedida, ela pode usar a reação para se mover até seu deslocamento de modo a não ficar mais cercada pela muralha.", "A muralha pode ter qualquer forma que você desejar, embora não possa ocupar o mesmo espaço que uma criatura ou objeto. A muralha não precisa ser vertical nem se apoiar em uma fundação firme. Ela precisa, porém, se fundir e ser sustentada solidamente por pedra existente. Assim, você pode usar esta magia para atravessar um abismo ou criar uma rampa.", "Se criar um vão com mais de 6 metros de comprimento, você precisa reduzir pela metade o tamanho de cada painel para criar suportes. Você pode moldar grosseiramente a muralha para criar ameias, torreões e assim por diante.", "A muralha é um objeto de pedra que pode ser danificado e, portanto, rompido. Cada painel tem CA 15 e 30 pontos de vida por 2,5 cm de espessura. Reduzir um painel a 0 pontos de vida o destrói e pode fazer painéis conectados desabarem, a critério do Mestre.", "Se você mantiver a concentração nesta magia por toda a duração, a muralha se torna permanente e não pode ser dissipada. Caso contrário, a muralha desaparece quando a magia termina."] },
]
